From 94e5d19094463c49a6033b96f5f6deecf1f4dd55 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:39:41 +0100
Subject: [PATCH] dataengines/powermanagement: read inhibitions as PowerDevil
 sends them

PowerDevil sends ListInhibitions and InhibitionsChanged as lists of string
lists, but the engine asked for string pairs, so the reply was rejected and
inhibitions already active never showed up. Read them as string lists.

BUG: 523640
---
 src/dataengines/powermanagement/powermanagementengine.cpp | 5 ++---
 src/dataengines/powermanagement/powermanagementengine.h   | 2 +-
 2 files changed, 3 insertions(+), 4 deletions(-)

diff --git a/src/dataengines/powermanagement/powermanagementengine.cpp b/src/dataengines/powermanagement/powermanagementengine.cpp
index 62e2c1e..b641ee5 100644
--- a/src/dataengines/powermanagement/powermanagementengine.cpp
+++ b/src/dataengines/powermanagement/powermanagementengine.cpp
@@ -65,7 +65,6 @@ PowermanagementEngine::PowermanagementEngine(QObject *parent)
     , m_sources(basicSourceNames())
 {
     qDBusRegisterMetaType<QList<InhibitionInfo>>();
-    qDBusRegisterMetaType<InhibitionInfo>();
     qDBusRegisterMetaType<QList<QVariant>>();
     qDBusRegisterMetaType<QList<QVariantMap>>();
     init();
@@ -676,10 +675,10 @@ void PowermanagementEngine::inhibitionsChanged(const QList<InhibitionInfo> &adde
     }

     for (auto it = added.constBegin(); it != added.constEnd(); ++it) {
-        const QString &name = (*it).first;
+        const QString name = (*it).value(0);
         QString prettyName;
         QString icon;
-        const QString &reason = (*it).second;
+        const QString reason = (*it).value(1);

         populateApplicationData(name, &prettyName, &icon);

diff --git a/src/dataengines/powermanagement/powermanagementengine.h b/src/dataengines/powermanagement/powermanagementengine.h
index 6a3d763..62de254 100644
--- a/src/dataengines/powermanagement/powermanagementengine.h
+++ b/src/dataengines/powermanagement/powermanagementengine.h
@@ -18,7 +18,7 @@

 class SessionManagement;

-using InhibitionInfo = QPair<QString, QString>;
+using InhibitionInfo = QStringList;

 /**
  * This class provides runtime information about the battery and AC status
-- 
